/* Reset & Base Styles */
:root {
    --primary-black: #000000;
    --accent-purple: #7638FA;
    --accent-orange: #FF7A00;
    --bg-light: #F8F9FA;
    --bg-white: #FFFFFF;
    --text-primary: #111111;
    --text-secondary: #555555;
    --border-color: #EAEAEA;
    --radius-sm: 8px;
    --radius-md: 16px;
    --radius-lg: 24px;
    --radius-full: 9999px;
    --spacing-xs: 8px;
    --spacing-sm: 16px;
    --spacing-md: 32px;
    --spacing-lg: 64px;
    --spacing-xl: 96px;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: 'Plus Jakarta Sans', sans-serif;
    background-color: var(--bg-white);
    color: var(--text-primary);
    line-height: 1.5;
    -webkit-font-smoothing: antialiased;
}

a {
    text-decoration: none;
    color: inherit;
}

ul {
    list-style: none;
}

.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--spacing-sm);
}

/* Typography */
h1, h2, h3, h4 {
    font-weight: 700;
    line-height: 1.2;
    letter-spacing: -0.02em;
}

h2 {
    font-size: 2.5rem;
    margin-bottom: var(--spacing-md);
}

p {
    color: var(--text-secondary);
    font-size: 1.125rem;
    margin-bottom: var(--spacing-md);
}

/* Buttons */
.btn-primary {
    display: inline-block;
    background: var(--primary-black);
    color: var(--bg-white);
    padding: 12px 24px;
    border-radius: var(--radius-full);
    font-weight: 600;
    transition: transform 0.2s, background 0.2s;
    border: none;
    cursor: pointer;
}

.btn-primary:hover {
    background: #333;
    transform: translateY(-2px);
}

.btn-large {
    padding: 16px 36px;
    font-size: 1.125rem;
}

/* Header */
.site-header {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    background: rgba(255, 255, 255, 0.9);
    backdrop-filter: blur(10px);
    z-index: 1000;
    border-bottom: 1px solid var(--border-color);
}

.header-container {
    display: flex;
    justify-content: space-between;
    align-items: center;
    max-width: 1200px;
    margin: 0 auto;
    padding: 16px var(--spacing-sm);
}

.logo {
    display: flex;
    align-items: center;
    gap: 8px;
    font-weight: 800;
    font-size: 1.25rem;
    color: var(--primary-black);
}

.logo i {
    color: var(--accent-purple);
}

.desktop-nav .btn-login {
    font-weight: 600;
    color: var(--primary-black);
    padding: 8px 16px;
}

.desktop-nav .btn-login:hover {
    color: var(--accent-purple);
}

.hamburger-menu {
    display: none;
    background: none;
    border: none;
    cursor: pointer;
    color: var(--primary-black);
}

/* Mobile Nav Overlay */
.mobile-nav-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100vh;
    background: var(--bg-white);
    z-index: 2000;
    display: flex;
    flex-direction: column;
    transform: translateY(-100%);
    transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.mobile-nav-overlay.open {
    transform: translateY(0);
}

.mobile-nav-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 16px var(--spacing-sm);
    border-bottom: 1px solid var(--border-color);
}

.close-menu {
    background: none;
    border: none;
    cursor: pointer;
}

.mobile-nav-content {
    display: flex;
    flex-direction: column;
    padding: var(--spacing-md) var(--spacing-sm);
    gap: var(--spacing-md);
}

.mobile-link {
    font-size: 1.5rem;
    font-weight: 600;
    color: var(--primary-black);
}

.mobile-nav-footer {
    margin-top: auto;
    padding-top: var(--spacing-md);
}

/* Hero Section */
.hero-section {
    padding: 160px var(--spacing-sm) 80px;
    text-align: center;
    position: relative;
    overflow: hidden;
    max-width: 900px;
    margin: 0 auto;
}

.hero-title {
    font-size: 3.5rem;
    margin-bottom: var(--spacing-md);
    background: linear-gradient(135deg, var(--primary-black) 0%, #333 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

.hero-description {
    font-size: 1.25rem;
    max-width: 700px;
    margin: 0 auto var(--spacing-md);
}

/* Info Sections (Features, Safety, Creators) */
.info-section {
    padding: var(--spacing-lg) 0;
}

.alternate-bg {
    background-color: var(--bg-light);
}

.info-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-lg);
    align-items: center;
}

.info-grid.reverse {
    direction: rtl;
}

.info-grid.reverse > * {
    direction: ltr;
}

.info-text h2 {
    font-size: 2.25rem;
}

.section-link {
    font-weight: 600;
    color: var(--primary-black);
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-size: 1.125rem;
}

.section-link:hover {
    color: var(--accent-purple);
}

/* Visuals for Info Sections */
.info-visual {
    position: relative;
    height: 400px;
    border-radius: var(--radius-lg);
    background: linear-gradient(135deg, rgba(118, 56, 250, 0.1), rgba(255, 122, 0, 0.1));
    display: flex;
    justify-content: center;
    align-items: center;
    overflow: hidden;
}

.features-visual {
    background: linear-gradient(135deg, #FFEDD5, #F3E8FF);
}

.feature-mockup {
    background: white;
    padding: 16px 24px;
    border-radius: var(--radius-full);
    box-shadow: 0 10px 30px rgba(0,0,0,0.1);
    display: flex;
    align-items: center;
    gap: 12px;
    font-weight: 600;
    position: absolute;
}

.mockup-1 {
    transform: translateY(-40px) translateX(-40px);
    color: var(--accent-purple);
}

.mockup-2 {
    transform: translateY(40px) translateX(40px);
    color: var(--accent-orange);
}

.safety-visual {
    background: linear-gradient(135deg, #DCFCE7, #DBEAFE);
    flex-direction: column;
    gap: 24px;
}

.shield-icon-container {
    color: #10B981;
}

.safety-card {
    background: white;
    padding: 16px 24px;
    border-radius: var(--radius-full);
    box-shadow: 0 10px 30px rgba(0,0,0,0.1);
    display: flex;
    align-items: center;
    gap: 16px;
    font-weight: 500;
}

.toggle-track {
    width: 48px;
    height: 24px;
    background: #E5E7EB;
    border-radius: 12px;
    position: relative;
    transition: background 0.3s;
}

.toggle-track.active {
    background: #10B981;
}

.toggle-thumb {
    width: 20px;
    height: 20px;
    background: white;
    border-radius: 50%;
    position: absolute;
    top: 2px;
    left: 2px;
    transition: transform 0.3s;
}

.toggle-track.active .toggle-thumb {
    transform: translateX(24px);
}

.creators-visual {
    background: linear-gradient(135deg, #FEF3C7, #FEE2E2);
}

.chart-container {
    background: white;
    padding: 32px;
    border-radius: var(--radius-lg);
    box-shadow: 0 10px 30px rgba(0,0,0,0.1);
    display: flex;
    align-items: center;
    gap: 24px;
}

.chart-container i {
    color: var(--accent-purple);
}

.chart-stats {
    display: flex;
    flex-direction: column;
}

.stat-num {
    font-size: 2rem;
    font-weight: 800;
    color: var(--primary-black);
}

.stat-label {
    color: var(--text-secondary);
    font-weight: 500;
}

/* Tagline Banner */
.tagline-banner {
    background: linear-gradient(90deg, var(--accent-purple), var(--accent-orange));
    padding: var(--spacing-xl) var(--spacing-sm);
    text-align: center;
    color: white;
}

.tagline-banner h2 {
    font-size: 3rem;
    margin: 0;
    max-width: 800px;
    margin: 0 auto;
}

/* News Section */
.news-section {
    padding: var(--spacing-xl) 0;
    overflow: hidden;
}

.news-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-bottom: var(--spacing-md);
}

.section-label {
    color: var(--accent-purple);
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-size: 0.875rem;
    display: block;
    margin-bottom: 8px;
}

.news-header h2 {
    margin: 0;
    font-size: 2rem;
}

.view-more {
    font-weight: 600;
    color: var(--primary-black);
    display: flex;
    align-items: center;
    gap: 4px;
}

.view-more:hover {
    color: var(--accent-orange);
}

.news-carousel {
    display: flex;
    gap: 24px;
    overflow-x: auto;
    padding-bottom: 24px;
    scroll-snap-type: x mandatory;
    scrollbar-width: none; /* Firefox */
}

.news-carousel::-webkit-scrollbar {
    display: none; /* Chrome/Safari/Edge */
}

.news-card {
    min-width: 320px;
    width: 320px;
    scroll-snap-align: start;
    display: flex;
    flex-direction: column;
    gap: 16px;
    cursor: pointer;
}

.card-thumbnail {
    height: 200px;
    border-radius: var(--radius-md);
    background-color: var(--border-color);
    background-size: cover;
    background-position: center;
    transition: transform 0.3s;
}

.news-card:hover .card-thumbnail {
    transform: scale(1.02);
}

.card-bg-1 { background: linear-gradient(135deg, #a855f7, #ec4899); }
.card-bg-2 { background: linear-gradient(135deg, #f97316, #eab308); }
.card-bg-3 { background: linear-gradient(135deg, #3b82f6, #2dd4bf); }
.card-bg-4 { background: linear-gradient(135deg, #ec4899, #f43f5e); }

.card-content {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.tags {
    display: flex;
    gap: 8px;
    flex-wrap: wrap;
}

.tag {
    font-size: 0.75rem;
    font-weight: 700;
    color: var(--accent-purple);
    background: rgba(118, 56, 250, 0.1);
    padding: 4px 8px;
    border-radius: 4px;
}

.card-title {
    font-size: 1.125rem;
    line-height: 1.4;
    font-weight: 600;
    display: -webkit-box;
    -webkit-line-clamp: 3;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

.card-date {
    color: var(--text-secondary);
    font-size: 0.875rem;
}

/* CTA Download Section */
.cta-download {
    padding: var(--spacing-xl) var(--spacing-sm);
    text-align: center;
    background: var(--bg-light);
}

.cta-container h2 {
    font-size: 3rem;
    margin-bottom: 8px;
}

.cta-container p {
    font-size: 1.5rem;
    margin-bottom: var(--spacing-md);
}

.store-buttons {
    display: flex;
    justify-content: center;
    gap: 16px;
    flex-wrap: wrap;
}

.btn-store {
    display: flex;
    align-items: center;
    gap: 12px;
    background: var(--primary-black);
    color: white;
    padding: 12px 24px;
    border-radius: var(--radius-md);
    font-weight: 600;
    transition: transform 0.2s, background 0.2s;
}

.btn-store:hover {
    background: #333;
    transform: translateY(-2px);
}

/* Footer */
.site-footer {
    background: var(--bg-white);
    padding: var(--spacing-xl) 0 var(--spacing-md);
    border-top: 1px solid var(--border-color);
}

.footer-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
    gap: var(--spacing-lg);
    margin-bottom: var(--spacing-xl);
}

.footer-col h4 {
    font-size: 1rem;
    margin-bottom: 24px;
    color: var(--primary-black);
}

.footer-col a {
    display: block;
    color: var(--text-secondary);
    margin-bottom: 12px;
    transition: color 0.2s;
}

.footer-col a:hover {
    color: var(--accent-purple);
}

.footer-bottom {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 24px;
    padding-top: var(--spacing-md);
    border-top: 1px solid var(--border-color);
}

.footer-bottom-left {
    display: flex;
    align-items: center;
    gap: 32px;
    flex-wrap: wrap;
}

.language-selector {
    display: flex;
    align-items: center;
    gap: 4px;
    font-weight: 600;
    color: var(--text-secondary);
    cursor: pointer;
}

.social-icons {
    display: flex;
    gap: 16px;
}

.social-icons a {
    color: var(--text-secondary);
    font-size: 1.25rem;
    transition: color 0.2s;
}

.social-icons a:hover {
    color: var(--primary-black);
}

.footer-legal {
    display: flex;
    gap: 16px;
    color: var(--text-secondary);
    font-size: 0.875rem;
}

.footer-legal a:hover {
    color: var(--primary-black);
}

/* Responsive Design */
@media (max-width: 768px) {
    :root {
        --spacing-xl: 64px;
        --spacing-lg: 48px;
    }

    .desktop-nav {
        display: none;
    }

    .hamburger-menu {
        display: block;
    }

    .hero-title {
        font-size: 2.5rem;
    }

    .info-grid, .info-grid.reverse {
        grid-template-columns: 1fr;
        direction: ltr;
    }

    .info-grid.reverse > * {
        direction: ltr;
    }

    .tagline-banner h2 {
        font-size: 2rem;
    }

    .news-header {
        flex-direction: column;
        align-items: flex-start;
        gap: 16px;
    }

    .cta-container h2 {
        font-size: 2.25rem;
    }

    .footer-bottom {
        flex-direction: column;
        align-items: flex-start;
    }
}

// Mobile Menu Toggle
const menuToggle = document.getElementById('menu-toggle');
const menuClose = document.getElementById('menu-close');
const mobileNav = document.getElementById('mobile-nav');

if (menuToggle && menuClose && mobileNav) {
    menuToggle.addEventListener('click', () => {
        mobileNav.classList.add('open');
        document.body.style.overflow = 'hidden'; // Prevent scrolling when menu is open
    });

    menuClose.addEventListener('click', () => {
        mobileNav.classList.remove('open');
        document.body.style.overflow = '';
    });
}

// Close mobile menu when a link is clicked
const mobileLinks = document.querySelectorAll('.mobile-link');
mobileLinks.forEach(link => {
    link.addEventListener('click', () => {
        mobileNav.classList.remove('open');
        document.body.style.overflow = '';
    });
});

// Interactive toggle in Safety Section
const toggleTrack = document.querySelector('.toggle-track');
const toggleText = document.querySelector('.safety-card span');

if (toggleTrack && toggleText) {
    toggleTrack.addEventListener('click', () => {
        toggleTrack.classList.toggle('active');
        if (toggleTrack.classList.contains('active')) {
            toggleText.textContent = 'Content Filter Active';
        } else {
            toggleText.textContent = 'Content Filter Inactive';
        }
    });
}

// Enable dragging on news carousel for desktop
const carousel = document.getElementById('news-carousel');

if (carousel) {
    let isDown = false;
    let startX;
    let scrollLeft;

    carousel.addEventListener('mousedown', (e) => {
        isDown = true;
        carousel.style.cursor = 'grabbing';
        carousel.style.scrollSnapType = 'none'; // Disable snap during drag
        startX = e.pageX - carousel.offsetLeft;
        scrollLeft = carousel.scrollLeft;
    });

    carousel.addEventListener('mouseleave', () => {
        isDown = false;
        carousel.style.cursor = 'grab';
        carousel.style.scrollSnapType = 'x mandatory';
    });

    carousel.addEventListener('mouseup', () => {
        isDown = false;
        carousel.style.cursor = 'grab';
        carousel.style.scrollSnapType = 'x mandatory';
    });

    carousel.addEventListener('mousemove', (e) => {
        if (!isDown) return;
        e.preventDefault();
        const x = e.pageX - carousel.offsetLeft;
        const walk = (x - startX) * 2; // Scroll-fast
        carousel.scrollLeft = scrollLeft - walk;
    });
}

