/* Hero Visuals */
.hero-visual {
    position: relative;
    height: 300px;
    margin-top: var(--spacing-lg);
    display: flex;
    justify-content: center;
    align-items: center;
}

.gradient-sphere {
    position: absolute;
    width: 200px;
    height: 200px;
    background: radial-gradient(circle at 30% 30%, var(--accent-purple), var(--accent-orange));
    border-radius: 50%;
    filter: blur(40px);
    opacity: 0.6;
    animation: float 6s ease-in-out infinite;
}

.glass-card {
    background: rgba(255, 255, 255, 0.8);
    backdrop-filter: blur(20px);
    border: 1px solid rgba(255, 255, 255, 0.5);
    padding: 24px;
    border-radius: var(--radius-lg);
    box-shadow: 0 20px 40px rgba(0,0,0,0.05);
    position: absolute;
}

.glass-card i {
    color: var(--primary-black);
}

.left-card {
    transform: translateX(-80px) rotate(-10deg);
    animation: float-slow 8s ease-in-out infinite;
}

.right-card {
    transform: translateX(80px) rotate(10deg);
    animation: float-slow 7s ease-in-out infinite alternate;
}

@keyframes float {
    0% { transform: translateY(0px) scale(1); }
    50% { transform: translateY(-20px) scale(1.05); }
    100% { transform: translateY(0px) scale(1); }
}

@keyframes float-slow {
    0% { transform: translateX(var(--tx, -80px)) rotate(var(--rot, -10deg)) translateY(0px); }
    50% { transform: translateX(var(--tx, -80px)) rotate(var(--rot, -10deg)) translateY(-15px); }
    100% { transform: translateX(var(--tx, -80px)) rotate(var(--rot, -10deg)) translateY(0px); }
}

.left-card {
    --tx: -80px;
    --rot: -10deg;
}

.right-card {
    --tx: 80px;
    --rot: 10deg;
}
EOF
